// ReviewCols holds typed orm.Column/orm.NullableColumn references for Review,
// used to build type-safe predicates, order terms and assignments.
var ReviewCols = struct {
	ID        orm.Column[Review, string]
	ProductID orm.Column[Review, string]
	UserID    orm.Column[Review, string]
	Rating    orm.Column[Review, int32]
	Body      orm.Column[Review, string]
	CreatedAt orm.Column[Review, time.Time]
}{
	ID:        orm.NewColumn[Review, string]("reviews", "id"),
	ProductID: orm.NewColumn[Review, string]("reviews", "product_id"),
	UserID:    orm.NewColumn[Review, string]("reviews", "user_id"),
	Rating:    orm.NewColumn[Review, int32]("reviews", "rating"),
	Body:      orm.NewColumn[Review, string]("reviews", "body"),
	CreatedAt: orm.NewColumn[Review, time.Time]("reviews", "created_at"),
}

// Review mirrors the "Review" entity declared in the schema.
type Review struct {
	ID        string    `json:"id"`
	ProductID string    `json:"product_id"`
	UserID    string    `json:"user_id"`
	Rating    int32     `json:"rating"`
	Body      string    `json:"body"`
	CreatedAt time.Time `json:"created_at"`
}

// Scan reads one row, whose columns must be in Reviews.Columns() order, into e.
func (e *Review) Scan(row orm.Row) error {
	var rawCreatedAt string
	if err := row.Scan(&e.ID, &e.ProductID, &e.UserID, &e.Rating, &e.Body, &rawCreatedAt); err != nil {
		return fmt.Errorf("[review] scan error: %w", err)
	}

	valCreatedAt, errCreatedAt := time.Parse(time.RFC3339Nano, rawCreatedAt)
	if errCreatedAt != nil {
		return fmt.Errorf("[review] parse created_at error: %w", errCreatedAt)
	}

	e.CreatedAt = valCreatedAt

	return nil
}

// Columns lists Review's columns in field-declaration order; Scan reads a
// row's columns in exactly this order.
func (Review) Columns() []string {
	return []string{"id", "product_id", "user_id", "rating", "body", "created_at"}
}

